/* Vidéoprojecteurs (option model de la carte TV) : photo détourée + calques animés.
   projector = vidéoprojecteur classique (focale courte), projector_compact = compact laser (ultra-courte focale).
   Calques : faisceau de lumière + halo de l'objectif (allumé, montée en puissance au démarrage), voyant d'état
   (éteint / veille rouge / allumé vert), photo grisée éteinte. Sans model : la télé d'origine. */
const PJ_IMG = {
  projector: { img: "data:image/webp;base64,", x: 4, y: 50, w: 112, h: 40.0, lens: [0.653, 0.55], led: [0.883, 0.40], beam: 44 },
  projector_compact: { img: "data:image/webp;base64,", x: 24, y: 44, w: 72, h: 58.4, lens: [0.66, 0.58], led: [0.88, 0.84], beam: 52 },
};
// vrai si la carte TV est configurée en vidéoprojecteur (model: projector / projector_compact)
const tvProjector = (c) => /^projector|^compact/.test(String((c && c.model) || "").toLowerCase().replace(/[^a-z_]/g, ""));
const PJ_TV = SVG.tv;
SVG.tv = (c) => {
  const k = String((c && c.model) || "").toLowerCase().replace(/[^a-z_]/g, "");
  const g = PJ_IMG[k === "projector_compact" || k === "compact" ? "projector_compact" : k === "projector" ? "projector" : ""];
  if (!g) return PJ_TV(c);
  const lx = +(g.x + g.w * g.lens[0]).toFixed(1), ly = +(g.y + g.h * g.lens[1]).toFixed(1);
  const dx = +(g.x + g.w * g.led[0]).toFixed(1), dy = +(g.y + g.h * g.led[1]).toFixed(1), bw = g.beam;
  return `<defs>${DEFS}
<linearGradient id="ID-pjb" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".75"/><stop offset=".7" stop-color="#cfe9ff" stop-opacity=".12"/><stop offset="1" stop-color="#cfe9ff" stop-opacity="0"/></linearGradient>
<radialGradient id="ID-pjg"><stop offset="0" stop-color="#fff" stop-opacity=".95"/><stop offset=".35" stop-color="#9fd8ff" stop-opacity=".6"/><stop offset="1" stop-color="#9fd8ff" stop-opacity="0"/></radialGradient></defs>
<g class="pj">
<ellipse cx="60" cy="${+(g.y + g.h + 1.5).toFixed(1)}" rx="${+(g.w * 0.42).toFixed(1)}" ry="2.4" fill="url(#ID-shadow)"/>
<g class="pj-beam"><path d="M${lx - 2} ${ly}L${lx - bw} 132L${lx + bw} 132L${lx + 2} ${ly}z" fill="url(#ID-pjb)"/></g>
<image class="pj-photo" href="${g.img}" x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}" preserveAspectRatio="none"/>
<circle class="pj-glow" cx="${lx}" cy="${ly}" r="${+(g.w * 0.16).toFixed(1)}" fill="url(#ID-pjg)"/>
<circle class="pj-led" cx="${dx}" cy="${dy}" r="1.3"/>
<rect class="tv-flash" width="0" height="0"/>
</g>`;
};

