 <g clip-path="url(#rttank)"><g class="tankw"><path class="wave" d="${wave}" fill="url(#rtwater)"/><ellipse class="ripple" cx="52" cy="100" rx="6" ry="2"/><ellipse class="ripple" cx="52" cy="100" rx="6" ry="2" style="animation-delay:-.6s"/></g></g>
