          const tmp = this._tmp(), ts = this._st(c.entity_temperature);
          this._hist = { t: c.entity_temperature ? pts(c.entity_temperature, (v) => tmp.conv(v, ts)) : [], h: c.entity_humidity ? pts(c.entity_humidity, (v) => v) : [] };
