      const L = this._live[key];
      if (fin(cur) && (!L.length || L[L.length - 1].v !== cur || now - L[L.length - 1].t > 10 * 60000)) L.push({ t: now, v: cur });
      while (L.length && L[0].t < now - 24 * 3600e3) L.shift();
