      const tcol = !fin(t) ? '#9e9e9e' : t < tMin - tmp.d(4) ? '#2f6fe0' : t < tMin ? '#4aa8e8' : t <= tMax ? '#3fbf8f' : t <= tMax + tmp.d(3) ? '#f2a33a' : '#e5482f';
