        try { out = await this._fetch(a, b, days); } catch (e) { out = { err: true, t: [], h: [], o: [], oh: [] }; }
        if (shift) ['t', 'h', 'o', 'oh'].forEach((k) => { out[k] = out[k].map((p) => ({ ...p, t: p.t + shift })); });
