      const bool = (name) => ({ name, selector: { boolean: {} }, default: true });
      const num = (name, def, max, unit) => ({ name, default: def, selector: { number: { min: 0, max, step: 1, mode: 'box', ...(unit ? { unit_of_measurement: unit } : {}) } } });
